SELECT
count(*)
FROM con_contract_before_rent_h ccbr
WHERE ccbr.project_id = #{projectId}
and ccbr.company_id = #{companyId}
and ccbr.cashflow_id = #{cashflowId}
and ccbr.zero_time_flag = 'N'

SELECT
*
FROM con_contract_before_rent_h ccbr
WHERE ccbr.project_id = #{projectId}
and ccbr.company_id = #{companyId}
and ccbr.calculate_settlement_date = #{calculateSettlementDate}
and ccbr.zero_time_flag = 'N'
order by ccbr.receivable_date asc

