select distinct ca.cashflow_id, ca.contract_id,ca.receivable_date- #{days} receivable_date,ca.receivable_date due_date from con_contract_before_rent_h ca,con_contract con where ca.receivable_date - #{days} = to_char(sysdate,'yyyy/mm/dd') and con.contract_id=ca.contract_id and ca.calculate_days is not null and ca.calculate_amount is not null
and con.lease_item_kind in
